// Z2404: sets of multiples generated by ES identity menus.
// Menu_K: n even (4/2m: scaling of 4/2), or n odd with n = -u (mod m), m = 4uC-1 <= K, (n+u)/m >= 1  [(*) line, FRONTIER 2.1]
// Menu M840: Mordell: n covered unless gcd(n,840)=1 and n mod 840 in {1,121,169,289,361,529}.
// For each menu: C = covered set, M(B) = {n : some divisor d>1 of n in C}, B = minimal elements of C (primitive set).
// Output: checkpoints x: #uncovered n<=x (complement of M(B)), its density, #uncovered primes, sum_{b in B, b<=x} 1/(b log b),
// sum over b in B prime / composite separately, |B| <= x.
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#define X 10000000
static unsigned char cov[X+1], mul[X+1], isB[X+1], comp[X+1];
int main(int argc,char**argv){
  int nmenus=argc-1;
  for(long i=2;i*i<=X;i++) if(!comp[i]) for(long j=i*i;j<=X;j+=i) comp[j]=1;
  for(int a=1;a<=nmenus;a++){
    memset(cov,0,sizeof cov); memset(mul,0,sizeof mul); memset(isB,0,sizeof isB);
    if(!strcmp(argv[a],"M840")){
      for(long n=2;n<=X;n++){ long r=n%840; int g=(n%2==0||n%3==0||n%5==0||n%7==0);
        int sq=(r==1||r==121||r==169||r==289||r==361||r==529); cov[n]= g || !sq; }
    } else {
      long K=atol(argv[a]);
      for(long n=2;n<=X;n+=2) cov[n]=1;
      for(long u=1;4*u-1<=K;u++) for(long C=1;4*u*C-1<=K;C++){ long m=4*u*C-1;
        long n0=m-u; if(n0<1) n0+=m; // n = -u mod m, n+u >= m
        for(long n=n0;n<=X;n+=m) if(n>=2) cov[n]=1; }
    }
    // closure and minimal elements
    for(long d=2;d<=X;d++) if(cov[d]){ if(!mul[d]) isB[d]=1; for(long k=d;k<=X;k+=d) mul[k]=1; }
    long cps[]={100000,1000000,10000000};
    long unc=0,uncp=0,nB=0,nBp=0; double S=0,Sp=0; int ci=0;
    printf("menu %s\n",argv[a]);
    for(long n=2;n<=X;n++){
      if(!mul[n]){ unc++; if(!comp[n]) uncp++; }
      if(isB[n]){ nB++; double w=1.0/(n*log((double)n)); S+=w; if(!comp[n]){Sp+=w;nBp++;} }
      if(n==cps[ci]){ printf("  x=%ld uncovered=%ld dens=%.6f uncov_primes=%ld |B|=%ld (primes %ld) S_B=%.6f S_Bprime=%.6f S_Bcomp=%.6f\n",
                       n,unc,(double)unc/n,uncp,nB,nBp,S,Sp,S-Sp); ci++; if(ci==3) break; }
    }
    fflush(stdout);
  }
  return 0;
}
